// The day's affirmation in Greek, for the country pages in Greek. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Δεν χρειάζεται να τα κάνεις όλα σήμερα. Το επόμενο μικρό βήμα φτάνει.\", \"Η κούραση δεν είναι αποτυχία. Είσαι κουρασμένη επειδή είσαι εκεί, κάθε μέρα.\", \"Τα πιάτα μπορούν να περιμένουν. Έχεις δικαίωμα να καθίσεις πέντε λεπτά.\", \"Δημητριακά για βραδινό; Κι αυτό μετράει ως φαγητό για την οικογένειά σου.\", \"Την ξεκούραση δεν χρειάζεται να την κερδίσεις. Μπορείς να ξεκουραστείς τώρα.\", \"Κάποιες μέρες η νίκη είναι ότι όλοι φτάσαμε ως την ώρα του ύπνου. Είναι αληθινή νίκη.\", \"Κάνεις πολύ περισσότερα απ’ όσα βλέπει κανείς. Εγώ τα βλέπω.\", \"Ένα ακατάστατο σπίτι και αγαπημένα παιδιά. Καλή ανταλλαγή.\", \"Σε μια δύσκολη μέρα, το καλύτερό σου μοιάζει αλλιώς, και πάλι μετράει.\", \"Μια βαθιά ανάσα. Χαλάρωσε τους ώμους. Τα πας καλά.\", \"Είναι εντάξει να κατεβάσεις τον πήχη σήμερα. Θα τον ανεβάσεις ξανά άλλη μέρα.\", \"Το να ζητάς βοήθεια είναι δύναμη, όχι αδυναμία.\", \"Έχεις δικαίωμα να πεις όχι σε ακόμα ένα πράγμα.\", \"Αν σήμερα ένιωσες μοναξιά, δεν είσαι η μόνη μαμά που ένιωσε έτσι. Είμαστε πολλές.\", \"Σου αξίζει μια φίλη που ρωτάει πώς είσαι και περιμένει την απάντηση.\", \"Είναι εντάξει να κάνεις εσύ το πρώτο βήμα. Οι περισσότερες μαμάδες ελπίζουν να το κάνει κάποια.\", \"Το ότι νιώθεις αόρατη δεν σημαίνει ότι δεν μετράς. Μετράς πάρα πολύ.\", \"Αυτά που νιώθεις έχουν λογική. Δεν είσαι «υπερβολική».\", \"Εδώ δεν χρειάζεται να εξηγήσεις τη δύσκολη μέρα σου. Σε καταλαβαίνουμε.\", \"Ένα μήνυμα σε μια άλλη μαμά που λέει «κι εγώ» μπορεί να αλλάξει όλη τη μέρα.\", \"Τάισμα, άλλαγμα, νανούρισμα, και ξανά απ’ την αρχή. Είναι αληθινή δουλειά, ακόμα κι όταν μοιάζει με απλό κάθισμα.\", \"Εσύ και το μωρό σου ακόμα γνωρίζεστε. Δεν υπάρχει βιασύνη.\", \"Οι μέρες με ένα νεογέννητο είναι μεγάλες. Αυτή η περίοδος δεν θα κρατήσει για πάντα.\", \"Αν το μόνο που έκανες σήμερα ήταν να κρατήσεις έναν μικρό άνθρωπο χορτάτο και ζεστό, έκανες σπουδαία δουλειά.\", \"Δεν χρειάζεται να γίνεις γρήγορα όπως πριν. Μπορείς απλώς να είσαι εκεί που είσαι.\", \"Όπως κι αν τρέφεται το μωρό σου, το φροντίζεις. Αυτό μετράει.\", \"Μπορείς να έχεις λίγο ύπνο και πολλή αγάπη ταυτόχρονα.\", \"Κράτα το μωρό αγκαλιά και άσε το σπίτι. Το σπίτι θα είναι ακόμα εδώ.\", \"Ένα ξέσπασμα στο σούπερ μάρκετ δεν σε κάνει κακή μαμά. Σημαίνει ότι έχεις ένα νήπιο.\", \"Τα μικρά δοκιμάζουν τα όρια επειδή νιώθουν ασφάλεια μαζί σου.\", \"Έμεινες ήρεμη ένα λεπτό περισσότερο από χθες. Αυτό μετράει.\", \"Αν θύμωσες, μια αγκαλιά κι ένα «συγγνώμη» διορθώνουν πολλά. Και τους μαθαίνουν κάτι καλό.\", \"Κολλημένα χεράκια, δυνατές φωνές, μεγάλα συναισθήματα. Μεγαλώνεις έναν ολόκληρο άνθρωπο.\", \"Το πέμπτο «γιατί;» της ώρας είναι ένα μικρό μυαλό που μεγαλώνει.\", \"Δεν χρειάζεσαι τέλεια μέρα για να φτιάξεις μια χαρούμενη ανάμνηση.\", \"Μια πόρτα που χτυπάει δεν είναι το τέλος της ιστορίας. Άφησε το φως αναμμένο.\", \"Ο έφηβός σου μπορεί να μην το λέει, αλλά η σταθερή σου παρουσία μετράει.\", \"Το να είσαι η ήρεμη του σπιτιού είναι δύσκολη δουλειά. Και την κάνεις.\", \"Μερικές από τις καλύτερες κουβέντες γίνονται στο αυτοκίνητο. Συνέχισε να οδηγείς.\", \"Απομακρύνονται για να μεγαλώσουν, όχι για να σε αφήσουν πίσω.\", \"Δεν χρειάζεται να έχεις όλες τις απαντήσεις. Το να ακούς είναι μεγάλο μέρος.\", \"Τα μεγάλα παιδιά σε χρειάζονται ακόμα, απλώς πιο αθόρυβα.\", \"Το να τα βγάζεις πέρα μόνη θέλει μια δύναμη που οι περισσότεροι δεν βλέπουν ποτέ.\", \"Είσαι αρκετή μαμά για το παιδί σου. Πάντα ήσουν.\", \"Δύο χέρια, εκατό δουλειές. Να είσαι επιεικής με τον εαυτό σου.\", \"Τα παιδιά σου μαθαίνουν, βλέποντάς σε, πώς είναι ένας δυνατός, τρυφερός άνθρωπος.\", \"Το διάλειμμα δεν είναι εγκατάλειψη. Έτσι αντέχεις.\", \"Κανείς δεν κρατάει σκορ. Η αγάπη και το να είσαι εκεί, αυτά μετράνε.\", \"Το πένθος και η αγάπη έρχονται από το ίδιο μέρος. Η απουσία που νιώθεις δείχνει πόσο αγάπησες.\", \"Δεν υπάρχει σωστό χρονοδιάγραμμα για το πένθος. Πάρε όσο χρόνο χρειάζεσαι.\", \"Στις δύσκολες επετείους, να είσαι τόσο τρυφερή με τον εαυτό σου όσο θα ήσουν με μια φίλη.\", \"Μπορείς να κουβαλάς λύπη και να γελάς με τα παιδιά σου. Και τα δύο είναι αληθινά.\", \"Αν έχασες μια εγκυμοσύνη ή ένα μωρό, η απώλεια είναι αληθινή, και η αγάπη σου επίσης.\", \"Κάποιες μέρες το πένθος είναι σιωπηλό και κάποιες φωνάζει. Και τα δύο είναι εντάξει.\", \"Τα λίγα χρήματα δεν σημαίνουν λίγη αγάπη.\", \"Τα παιδιά σου θα θυμούνται τον χρόνο μαζί σου περισσότερο από τα πράγματα που αγόρασες.\", \"Το να ρωτάς για βοήθεια με τους λογαριασμούς είναι έξυπνο, όχι ντροπή. Γι’ αυτό υπάρχει η βοήθεια.\", \"Ένα δωρεάν απόγευμα στο πάρκο μπορεί να είναι η καλύτερη μέρα της εβδομάδας.\", \"Τα έβγαλες πέρα μια εβδομάδα ακόμα. Αυτό θέλει πραγματική ικανότητα.\", \"Η έγνοια για τα χρήματα κουράζει. Κουβαλάς πολλά, κι όμως είσαι ακόμα εδώ.\", \"Ήπιες ένα ποτήρι νερό σήμερα. Ξεκίνα από εκεί.\", \"Όλοι βγήκαν από την πόρτα. Τα παπούτσια ίσως δεν ταίριαζαν. Και πάλι νίκη.\", \"Έκανες το τηλεφώνημα που φοβόσουν. Ήταν γενναίο.\", \"Γέλασες σήμερα. Κράτα το.\", \"Ένα ζεστό φαγητό, ένα καθαρό μπλουζάκι, ένα παραμύθι πριν τον ύπνο. Τα μικρά πράγματα φτιάχνουν μια παιδική ηλικία.\", \"Σήμερα φέρθηκες καλά σε κάποιον, έστω κι αν ήταν μόνο ο εαυτός σου.\", \"Πρόοδος, όχι τελειότητα. Σήμερα προχώρησες.\", \"Τελείωσες ένα πράγμα από τη λίστα. Ένα παραπάνω από κανένα.\", \"Είσαι καλή μαμά. Το ότι σε απασχολεί δείχνει πόσο νοιάζεσαι.\", \"Είσαι πολύ περισσότερα από όσα προλαβαίνεις σε μια μέρα.\", \"Τα παιδιά σου δεν χρειάζονται τέλεια μαμά. Χρειάζονται εσένα, και σε έχουν.\", \"Να είσαι υπομονετική με τον εαυτό σου όσο είσαι με τα παιδιά σου.\", \"Έχεις δικαίωμα να πιάνεις χώρο, να θέλεις πράγματα και να έχεις τα δικά σου όνειρα.\", \"Ένα λάθος δεν σβήνει την αγάπη. Το αύριο είναι μια καινούργια αρχή.\", \"Είσαι ο κόσμος όλος για κάποιον, και είσαι και ο δικός σου άνθρωπος.\", \"Είναι εντάξει να μην απολαμβάνεις κάθε λεπτό. Μπορείς και πάλι να αγαπάς τα παιδιά σου με όλη σου την καρδιά.\", \"Δεν υπάρχει ένας σωστός τρόπος να είσαι μαμά. Ο δικός σου τρόπος χωράει.\", \"Όπως στη στάση του δέντρου, είναι εντάξει να ταλαντεύεσαι. Μπορείς να βρεις ξανά την ισορροπία σου.\", \"Στερέωσε τα πόδια σου όπως στη στάση του βουνού. Είσαι πιο σταθερή απ’ όσο νιώθεις.\", \"Πολεμιστής δύο: δυνατά πόδια, ανοιχτά χέρια. Αυτή είσαι εσύ, απέναντι σε αυτή την εβδομάδα.\", \"Εισπνοή στο τέσσερα, εκπνοή στο τέσσερα. Είσαι εδώ, και τα πας καλά.\", \"Ανοίξου πλατιά σαν αστέρι. Έχεις δικαίωμα να πιάνεις χώρο.\", \"Ένα φαρδύ, χαμηλό κάθισμα είναι δύσκολο να το κρατήσεις. Το ίδιο και μια μεγάλη μέρα. Και την κρατάς.\", \"Μπορείς να γέρνεις σαν μισοφέγγαρο και να στέκεσαι ακόμα όρθια.\", \"Δεν χρειάζεται να φτάσεις ακόμα τα δάχτυλα των ποδιών. Κάθε λίγο τέντωμα μετράει.\", \"Στάση του τριγώνου: ένα χέρι κάτω, ένα χέρι πάνω. Μείνε γειωμένη και συνέχισε να τεντώνεσαι.\", \"Είναι αργά. Ό,τι δεν έγινε σήμερα μπορεί να περιμένει ως αύριο.\", \"Ξύπνια με το μωρό τέτοια ώρα; Πολλές μαμάδες είναι ξύπνιες μαζί σου αυτή τη στιγμή.\", \"Το σπίτι ησύχασε. Αυτή η στιγμή είναι δική σου. Ανάσανε.\", \"Τα κατάφερες για σήμερα. Μόνο αυτό χρειαζόταν η μέρα.\", \"Αν το μυαλό σου τρέχει απόψε, γράψ’ τα και άφησέ τα να περιμένουν ως το πρωί.\", \"Ξεκούρασε τα μάτια σου. Αύριο ξεκινάς από την αρχή.\", \"Οι γιορτές μπορεί να είναι δύσκολες όσο και χαρούμενες. Ό,τι κι αν νιώθεις αυτή την εποχή, είναι εντάξει.\", \"Το τραπέζι δεν χρειάζεται να είναι τέλειο. Οι άνθρωποι γύρω του είναι αυτό που μετράει.\", \"Αν φέτος σου λείπει κάποιος από το τραπέζι, να είσαι τρυφερή με την καρδιά σου.\", \"Ευχαριστώ, μαμά, για κάθε φαγητό, κάθε διαδρομή και κάθε αγκαλιά.\", \"Δεν χρειάζεται να φιλοξενήσεις, να ψήσεις ή να χαμογελάς συνέχεια. Μια απλή γιορτή είναι κι αυτή γιορτή.\", \"Το καλύτερο δώρο που παίρνουν φέτος τα παιδιά σου είναι χρόνος μαζί σου.\", \"Μια μικρή γιορτή είναι κι αυτή γεμάτη αγάπη. Δεν χρειάζονται πολλά χρήματα για να γίνει ξεχωριστή.\", \"Κρύες μέρες, ζεστές αγκαλιές. Εσύ είσαι η ζεστή γωνιά του σπιτιού σου.\", \"Είναι εντάξει να παραλείψεις λίγη από τη γιορτινή φούρια. Η ηρεμία είναι κι αυτή δώρο.\", \"Αν αυτή η εποχή σε βαραίνει φέτος, δεν είσαι μόνη. Μία μέρα τη φορά.\"]";D.body.appendChild(e)})();
